COMMENT ON COLUMN GAME.ID IS 'the unique identifier of the game';
COMMENT ON COLUMN GAME.GENRE_ID IS 'the id of the game genre';
ALTER TABLE GAME MODIFY (GENRE_ID ANNOTATIONS (ADD value_description 'commonsense evidence:If game A and game B have the same genre, the user who likes game A may also like game B.'));
COMMENT ON COLUMN GAME.GAME_NAME IS 'the name of the game';
COMMENT ON COLUMN GAME_PLATFORM.ID IS 'the unique identifier of the record';
COMMENT ON COLUMN GAME_PLATFORM.GAME_PUBLISHER_ID IS 'the id of the game publisher';
COMMENT ON COLUMN GAME_PLATFORM.PLATFORM_ID IS 'the id of the platform';
COMMENT ON COLUMN GAME_PLATFORM.RELEASE_YEAR IS 'the release year of the game';
COMMENT ON COLUMN GAME_PUBLISHER.ID IS 'the unique identifier of the game publisher';
COMMENT ON COLUMN GAME_PUBLISHER.GAME_ID IS 'the id of the game';
COMMENT ON COLUMN GAME_PUBLISHER.PUBLISHER_ID IS 'the id of the publisher';
ALTER TABLE GAME_PUBLISHER MODIFY (PUBLISHER_ID ANNOTATIONS (ADD value_description 'commonsense evidence:If game A and game B were published by the same publisher, the user who likes game A may also like game B if the user is a fan of the publisher company.'));
COMMENT ON COLUMN GENRE.ID IS 'the unique identifier of the game genre';
COMMENT ON COLUMN GENRE.GENRE_NAME IS 'the game genre';
ALTER TABLE GENRE MODIFY (GENRE_NAME ANNOTATIONS (ADD value_description 'commonsense evidence:The game genre can have a significant effect on the game. The genre refers to the category or type of game, such as action, adventure, strategy, or role-playing. The genre can determine the general style and gameplay of the game, as well as the expectations of the players. The genre can also affect the audience for the game, as different genres may appeal to different groups of players.'));
COMMENT ON COLUMN PLATFORM.ID IS 'the unique identifier of the game platform';
COMMENT ON COLUMN PLATFORM.PLATFORM_NAME IS 'the name of the platform';
ALTER TABLE PLATFORM MODIFY (PLATFORM_NAME ANNOTATIONS (ADD value_description 'commonsense evidence:The game platform, or the platform on which a game is played, can have a significant effect on the game. The platform can determine what hardware and software the game can run on, as well as the technical capabilities of the game. The platform can also affect the audience for the game, as different platforms may attract different groups of players.'));
COMMENT ON COLUMN PUBLISHER.ID IS 'the unique identifier of the game publisher';
COMMENT ON COLUMN PUBLISHER.PUBLISHER_NAME IS 'the name of the publisher';
ALTER TABLE PUBLISHER MODIFY (PUBLISHER_NAME ANNOTATIONS (ADD value_description 'commonsense evidence:The publisher is the company or organization that finances, produces, and distributes the game. The publisher can influence the development of the game by providing resources, guidance, and support to the game''s development team. The publisher can also affect the marketing and distribution of the game, as they are responsible for promoting the game and making it available to players.'));
COMMENT ON COLUMN REGION.ID IS 'the unique identifier of the region';
COMMENT ON COLUMN REGION.REGION_NAME IS 'the region name';
COMMENT ON COLUMN REGION_SALES.REGION_ID IS 'the id of the region';
COMMENT ON COLUMN REGION_SALES.GAME_PLATFORM_ID IS 'the id of the game platform';
COMMENT ON COLUMN REGION_SALES.NUM_SALES IS 'the number of sales in this region';
ALTER TABLE REGION_SALES MODIFY (NUM_SALES ANNOTATIONS (ADD value_description 'commonsense evidence:The number of games sold in the region = num_sales * 100000.The game platform with higher num_sales is more popular in the region.'));